{
  "name": "ARTIQ 固件构建服务客户端",
  "name_en": "ARTIQ Firmware Build Service Client",
  "manufacturer": "M-Labs",
  "description": "用于连接 ARTIQ 固件构建服务的网络客户端，可通过 WebSocket 登录、提交指定版本和变体的构建请求，并读取文本或 JSON 格式的返回结果。该服务常用于为实验室中的 ARTIQ 控制硬件准备固件或相关构建产物。",
  "description_en": "A network client for the ARTIQ firmware build service. It connects over WebSocket, logs in, submits build requests for specified versions and variants, and reads text or JSON replies. The service is typically used to prepare firmware or related build artifacts for ARTIQ laboratory control hardware.",
  "tag_hints": [
    "ARTIQ",
    "firmware build service",
    "WebSocket communication",
    "hardware variants",
    "lab control system",
    "JSON command interface"
  ],
  "actions": [
    {
      "action_name": "auto-init_websocket",
      "description": "初始化到构建服务的 WebSocket 连接。",
      "description_en": "Initialize the WebSocket connection to the build service."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与构建服务的连接。",
      "description_en": "Close the connection to the build service."
    },
    {
      "action_name": "auto-send_command",
      "description": "向构建服务发送命令。",
      "description_en": "Send a command to the build service."
    },
    {
      "action_name": "auto-read_line",
      "description": "读取一行文本返回。",
      "description_en": "Read a single line of text response."
    },
    {
      "action_name": "auto-read_reply",
      "description": "读取一条服务返回消息。",
      "description_en": "Read a reply message from the service."
    },
    {
      "action_name": "auto-read_json",
      "description": "读取 JSON 格式的返回数据。",
      "description_en": "Read a JSON-formatted response."
    },
    {
      "action_name": "auto-login",
      "description": "使用用户名和密码登录构建服务。",
      "description_en": "Log in to the build service with a username and password."
    },
    {
      "action_name": "auto-build",
      "description": "提交指定版本、修订和变体的构建请求，并可附带日志或实验性功能选项。",
      "description_en": "Submit a build request for a specified version, revision, and variant, with optional logging or experimental feature settings."
    },
    {
      "action_name": "auto-passwd",
      "description": "设置或更新服务账户密码。",
      "description_en": "Set or update the service account password."
    },
    {
      "action_name": "auto-get_variants",
      "description": "获取可用的构建变体列表。",
      "description_en": "Get the list of available build variants."
    },
    {
      "action_name": "auto-get_single_variant",
      "description": "获取单个可用的构建变体。",
      "description_en": "Get a single available build variant."
    },
    {
      "action_name": "auto-get_json",
      "description": "获取指定变体的 JSON 数据。",
      "description_en": "Get JSON data for the specified variant."
    }
  ]
}

